// arm-none-eabi. Detect these cases and issue a warning.
if (TC.getTriple().getOS() == llvm::Triple::UnknownOS &&
    TC.getTriple().getVendor() == llvm::Triple::UnknownVendor) {
  switch (TC.getTriple().getArch()) {
