5450	static bool isOffloadDeviceCC1JobCandidate(Command &Job) {
5451	  const Action &Source = Job.getSource();
5452	  if (!isa<CompileJobAction>(Source) && !isa<BackendJobAction>(Source))
5453	    return false;
5454	
5455	  if (Job.getBoundArch().empty() && !Source.getOffloadingArch().empty())
5456	    Job.setBoundArch(Source.getOffloadingArch());
5457	
5458	  if (Job.getBoundArch().empty())
5459	    return false;
5460	
5461	  if (StringRef(Job.getCreator().getName()) != "clang")
5462	    return false;
5463	
5464	  Action::OffloadKind OKind = Source.getOffloadingDeviceKind();
5465	  if (OKind != Action::OFK_None && OKind != Action::OFK_Host)
5466	    return true;
5467	
5468	  const llvm::Triple &Triple = Job.getCreator().getToolChain().getTriple();
5469	  return Triple.isAMDGPU() || Triple.isNVPTX() || Triple.isSPIROrSPIRV();
5470	}
