5472	static std::string getOffloadDeviceCC1ParallelJobGroup(const Command &Job) {
5473	  const Action &Source = Job.getSource();
5474	  // This key groups device cc1 jobs that can run in parallel. Jobs may differ
5475	  // by offload arch, but must have the same offload kind, target triple,
5476	  // action kind, and output type. For example, HIP compile jobs for gfx900 and
5477	  // gfx906 can share a group, but HIP and OpenMP jobs cannot.
5478	  return (Twine(Action::GetOffloadKindName(Source.getOffloadingDeviceKind())) +
5479	          ":" + Job.getCreator().getToolChain().getTripleString() + ":" +
5480	          Source.getClassName() + ":" + types::getTypeName(Source.getType()))
5481	      .str();
5482	}
