5484	static void claimAndDiagnoseOffloadJobs(const Driver &D, const ArgList &Args) {
5485	  auto OffloadJobs = tools::parseOffloadJobs(Args);
5486	  if (!OffloadJobs.A)
5487	    return;
5488	
5489	  if (!OffloadJobs.isValid())
5490	    D.Diag(diag::err_drv_invalid_int_value)
5491	        << OffloadJobs.A->getAsString(Args) << OffloadJobs.Value;
5492	
5493	  OffloadJobs.A->claim();
5494	}
5495	
5496	static void markOffloadDeviceCC1JobsForParallelExecution(Compilation &C) {
5497	  bool FoundCandidate = false;
5498	  for (auto &Job : C.getJobs()) {
5499	    if (!isOffloadDeviceCC1JobCandidate(Job))
5500	      continue;
5501	
5502	    Job.setOffloadDeviceParallelJobGroup(
5503	        getOffloadDeviceCC1ParallelJobGroup(Job));
5504	    FoundCandidate = true;
5505	  }
5506	
5507	  if (FoundCandidate)
5508	    claimAndDiagnoseOffloadJobs(C.getDriver(), C.getArgs());
5509	}
